cat > shape.mjs <<'EOF'
import { readFileSync } from "node:fs";

const body = readFileSync(process.argv[2], "utf8");
const plan = JSON.parse(readFileSync("evidence.json", "utf8")).plan;
const lines = body.trimEnd().split("\n");
const HEADINGS = ["What changes", "Why", "How it was checked", "What was not checked, and why",
  "Risk and rollback", "Where to look first", "References"];
const problems = [];

let last = -1;
for (const h of HEADINGS) {
  const at = lines.indexOf(`### ${h}`);
  if (at === -1) problems.push(`missing heading: ### ${h}`);
  else if (at < last) problems.push(`heading out of order: ### ${h}`);
  else last = at;
}

const fold = body.split("<details>")[0].split(/\s+/).filter(Boolean).length;
if (fold > 300) problems.push(`above the fold is ${fold} words; keep it under 300`);

for (const { id } of plan.qa_plan) {
  const row = lines.find((l) => l.startsWith(`| ${id}:`));
  if (!row) { problems.push(`${id} has no row in the checks table`); continue; }
  const [, , result, proof] = row.split("|").map((c) => c.trim());
  if (result === "pass" && !proof.startsWith("[proof](")) problems.push(`${id} says pass, with no link to proof`);
}

const blocks = body.split("```").filter((_, i) => i % 2 === 1);
for (const b of blocks) {
  const n = b.trim().split("\n").length;
  if (n > 15) problems.push(`a pasted block of ${n} lines; link long output instead`);
}

if (!/^Requested-by: @[\w-]+$/.test(lines.at(-1))) problems.push("the last line is not Requested-by: @<login>");

for (const p of problems) console.log(`✘ ${p}`);
console.log(problems.length ? `${problems.length} problem(s)` : `✔ the shape is right (${fold} words above the fold)`);
process.exitCode = problems.length ? 1 : 0;
EOF
node shape.mjs pr.md; echo "exit $?"

